const BASE_LON = 76.3540;
const BASE_LAT = 10.0120;
const LAT_M = 111320.0;
const LON_M = 111320.0 * 0.9848;

function makePolygon(minX, minY, maxX, maxY) {
  const coords = [
    [Number((BASE_LON + minX / LON_M).toFixed(7)), Number((BASE_LAT + minY / LAT_M).toFixed(7))],
    [Number((BASE_LON + maxX / LON_M).toFixed(7)), Number((BASE_LAT + minY / LAT_M).toFixed(7))],
    [Number((BASE_LON + maxX / LON_M).toFixed(7)), Number((BASE_LAT + maxY / LAT_M).toFixed(7))],
    [Number((BASE_LON + minX / LON_M).toFixed(7)), Number((BASE_LAT + maxY / LAT_M).toFixed(7))],
    [Number((BASE_LON + minX / LON_M).toFixed(7)), Number((BASE_LAT + minY / LAT_M).toFixed(7))]
  ];
  return { type: 'Polygon', coordinates: [coords] };
}

const PALETTE = [
  '#3E8ED0', '#2ECC71', '#F39C12', '#E74C3C', '#9B59B6', '#1ABC9C', '#D35400', '#34495E'
];

export function generateDynamicMockBuilding(ulpinStr) {
  let h = 0;
  for (let i = 0; i < ulpinStr.length; i++) {
    h += ulpinStr.charCodeAt(i);
  }
  const dx = (h % 200) + 10;
  const dy = ((h * 3) % 200) + 10;
  const geom = makePolygon(dx, dy, dx + 40, dy + 40);
  const fCount = Math.max(2, (h % 6) + 1);
  const height = fCount * 3.6;
  const floors = [];

  for (let i = 1; i <= fCount; i++) {
    const fUlpin = `${ulpinStr}-F${String(i).padStart(2, '0')}`;
    const color = PALETTE[i % PALETTE.length];
    floors.push({
      type: 'Feature',
      properties: {
        ulpin: fUlpin,
        building_ulpin: ulpinStr,
        floor_index: i,
        floor_name: `Floor ${i}`,
        z_min: Number(((i - 1) * 3.6).toFixed(1)),
        z_max: Number((i * 3.6).toFixed(1)),
        color,
        area_sqm: 1600.0,
        legal_status: 'Freehold Registered',
        tax_clearance: 'FY 2025-26 Paid'
      },
      geometry: geom
    });
  }

  return {
    type: 'Feature',
    properties: {
      ulpin: ulpinStr,
      building_id: h % 100,
      name: `Survey Parcel ${ulpinStr}`,
      floor_count: fCount,
      building_height: height,
      class_name: 'mixed_property',
      has_conflict: false,
      cadastral_survey: {
        survey_no: `Sy. ${(h % 100) * 12}/2`,
        village: 'Kakkanad Revenue Block',
        district: 'Ernakulam',
        state: 'Kerala',
        crs: 'EPSG:4326 (WGS84)'
      }
    },
    geometry: geom,
    floors
  };
}

export function getMockBuildingOrFloor(ulpinStr) {
  if (!ulpinStr) return null;
  const clean = ulpinStr.trim();
  if (MOCK_FLOORS_BY_ULPIN[clean]) return MOCK_FLOORS_BY_ULPIN[clean];
  if (MOCK_BUILDINGS_BY_ULPIN[clean]) return MOCK_BUILDINGS_BY_ULPIN[clean];

  // Case-insensitive check
  const floorMatch = Object.keys(MOCK_FLOORS_BY_ULPIN).find(k => k.toLowerCase() === clean.toLowerCase());
  if (floorMatch) return MOCK_FLOORS_BY_ULPIN[floorMatch];

  const bldgMatch = Object.keys(MOCK_BUILDINGS_BY_ULPIN).find(k => k.toLowerCase() === clean.toLowerCase());
  if (bldgMatch) return MOCK_BUILDINGS_BY_ULPIN[bldgMatch];

  // Check if it's a floor format on an existing building
  const matchFloor = clean.match(/^(.+)-(F|B)(\d+)$/i);
  if (matchFloor) {
    const parentUlpin = matchFloor[1];
    const parent = MOCK_BUILDINGS_BY_ULPIN[parentUlpin];
    if (parent && parent.floors) {
      const foundFloor = parent.floors.find(f => f.properties?.ulpin?.toLowerCase() === clean.toLowerCase());
      if (foundFloor) return foundFloor;
    }
  }

  return generateDynamicMockBuilding(clean);
}
